    def _resolve_friendly_unit_root_by_id(self, unit_id: str):
        token = str(unit_id or "").strip()
        if not token:
            return None
        army = self.player.get_army() if self.player is not None else None
        if army is None:
            return None
        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            get_root = getattr(unit, "get_attached_unit_root", None)
            root = get_root() if callable(get_root) else unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if root_id and root_id in seen:
                continue
            if root_id:
                seen.add(root_id)
            if root_id == token:
                return root
        return None

    def _rapid_ingress_position_within_unit(
        self,
        target_unit,
        position,
        source_unit,
        *,
        max_distance: float,
    ) -> bool:
        if target_unit is None or source_unit is None:
            return False
        if not isinstance(position, (list, tuple)) or len(position) < 2:
            return False
        try:
            x = float(position[0])
            y = float(position[1])
            z = float(position[2]) if len(position) > 2 else 0.0
        except (TypeError, ValueError):
            return False
        try:
            required = float(max_distance or 0.0)
        except (TypeError, ValueError):
            return False
        if required <= 0.0:
            return False
        try:
            from ..utility.aura_utils import horizontal_distance_between_bases_2d
        except Exception:
            return False

        target_bases = []
        target_models = list(getattr(target_unit, "models", []) or [])
        game_map = getattr(self.game, "map", None) if self.game is not None else None
        boundary_repulsors = []
        if game_map is not None:
            try:
                boundary_repulsors = list(game_map.get_battlefield_edge_repulsors() or [])
            except Exception:
                boundary_repulsors = []
        try:
            model_positions = target_unit.calculate_model_positions(
                x,
                y,
                game_map,
                boundary_repulsors=boundary_repulsors,
                avoid_friendly_units=False,
            )
        except Exception:
            model_positions = None

        if isinstance(model_positions, list) and model_positions:
            for model, pos in zip(target_models, model_positions):
                if model is None or not bool(getattr(model, "is_alive", True)):
                    continue
                try:
                    base = target_unit._create_potential_base(
                        float(pos[0]),
                        float(pos[1]),
                        float(pos[2]),
                        float(pos[3]),
                        model=model,
                    )
                except Exception:
                    base = None
                if base is not None:
                    target_bases.append(base)

        if not target_bases:
            for model in target_models:
                if model is None or not bool(getattr(model, "is_alive", True)):
                    continue
                try:
                    base = target_unit._create_potential_base(
                        x,
                        y,
                        z,
                        0.0,
                        model=model,
                    )
                except Exception:
                    base = None
                if base is not None:
                    target_bases.append(base)

        source_models = []
        get_source_models = getattr(source_unit, "get_attached_unit_models", None)
        if callable(get_source_models):
            source_models = list(get_source_models() or [])
        if not source_models:
            source_models = list(getattr(source_unit, "models", []) or [])
        if not source_models or not target_bases:
            return False

        for target_base in target_bases:
            for source_model in source_models:
                if source_model is None or not bool(getattr(source_model, "is_alive", True)):
                    continue
                source_base = getattr(source_model, "model_base", None)
                if source_base is None:
                    continue
                try:
                    dist = float(horizontal_distance_between_bases_2d(target_base, source_base))
                except Exception:
                    continue
                if dist <= float(required) + 1e-6:
                    return True
        return False

    def _rapid_ingress_position_within_point(
        self,
        target_unit,
        position,
        anchor_point,
        *,
        max_distance: float,
    ) -> bool:
        if target_unit is None:
            return False
        if not isinstance(position, (list, tuple)) or len(position) < 2:
            return False
        if not isinstance(anchor_point, (list, tuple)) or len(anchor_point) < 2:
            return False
        try:
            x = float(position[0])
            y = float(position[1])
            z = float(position[2]) if len(position) > 2 else 0.0
            anchor_x = float(anchor_point[0])
            anchor_y = float(anchor_point[1])
        except (TypeError, ValueError):
            return False
        try:
            required = float(max_distance or 0.0)
        except (TypeError, ValueError):
            return False
        if required <= 0.0:
            return False
        try:
            from ..utility.aura_utils import horizontal_distance_point_to_base_2d
        except Exception:
            return False

        target_bases = []
        target_models = list(getattr(target_unit, "models", []) or [])
        game_map = getattr(self.game, "map", None) if self.game is not None else None
        boundary_repulsors = []
        if game_map is not None:
            try:
                boundary_repulsors = list(game_map.get_battlefield_edge_repulsors() or [])
            except Exception:
                boundary_repulsors = []
        try:
            model_positions = target_unit.calculate_model_positions(
                x,
                y,
                game_map,
                boundary_repulsors=boundary_repulsors,
                avoid_friendly_units=False,
            )
        except Exception:
            model_positions = None

        if isinstance(model_positions, list) and model_positions:
            for model, pos in zip(target_models, model_positions):
                if model is None or not bool(getattr(model, "is_alive", True)):
                    continue
                try:
                    base = target_unit._create_potential_base(
                        float(pos[0]),
                        float(pos[1]),
                        float(pos[2]),
                        float(pos[3]),
                        model=model,
                    )
                except Exception:
                    base = None
                if base is not None:
                    target_bases.append(base)

        if not target_bases:
            for model in target_models:
                if model is None or not bool(getattr(model, "is_alive", True)):
                    continue
                try:
                    base = target_unit._create_potential_base(
                        x,
                        y,
                        z,
                        0.0,
                        model=model,
                    )
                except Exception:
                    base = None
                if base is not None:
                    target_bases.append(base)

        if not target_bases:
            return False
        for target_base in target_bases:
            try:
                dist = float(horizontal_distance_point_to_base_2d(target_base, anchor_x, anchor_y))
            except Exception:
                continue
            if dist <= float(required) + 1e-6:
                return True
        return False

    def _set_gift_of_the_prescient_rapid_ingress_setup_override(
        self,
        unit,
        *,
        min_distance: float = 3.0,
        source: str = "",
        expires_phase: str = "MOVEMENT_PHASE",
    ) -> None:
        if unit is None:
            return
        get_root = getattr(unit, "get_attached_unit_root", None)
        root = get_root() if callable(get_root) else unit
        if root is None:
            return
        sr = getattr(root, "special_rules", None)
        if not isinstance(sr, dict):
            sr = {}
        try:
            resolved_min = float(min_distance or 3.0)
        except (TypeError, ValueError):
            resolved_min = 3.0
        if resolved_min <= 0.0:
            resolved_min = 3.0
        source_name = str(source or "Gift of the Prescient").strip() or "Gift of the Prescient"
        phase_name = str(expires_phase or "MOVEMENT_PHASE").strip().upper() or "MOVEMENT_PHASE"
        sr["gift_of_the_prescient_deep_strike_min_distance"] = float(resolved_min)
        sr["gift_of_the_prescient_expires_phase"] = phase_name
        sr["gift_of_the_prescient_source"] = source_name
        root.special_rules = sr

    def _clear_gift_of_the_prescient_rapid_ingress_setup_override(self, unit) -> None:
        if unit is None:
            return
        get_root = getattr(unit, "get_attached_unit_root", None)
        root = get_root() if callable(get_root) else unit
        if root is None:
            return
        sr = getattr(root, "special_rules", None)
        if not isinstance(sr, dict):
            return
        sr.pop("gift_of_the_prescient_deep_strike_min_distance", None)
        sr.pop("gift_of_the_prescient_expires_phase", None)
        sr.pop("gift_of_the_prescient_source", None)
        root.special_rules = sr

    def _command_reroll_repeat_allowed(self, *, target_unit=None, candidates=None) -> bool:
        can_use_mirror_fn = getattr(self.player, "_target_unit_can_use_mirror_of_fates_command_reroll", None)
        can_use_datasheet_fn = getattr(
            self.player,
            "_target_unit_can_use_datasheet_command_reroll_stratagem_discount",
            None,
        )

        def _can_repeat(unit) -> bool:
            if unit is None:
                return False
            if callable(can_use_mirror_fn) and bool(can_use_mirror_fn(unit)):
                return True
            if callable(can_use_datasheet_fn) and bool(
                can_use_datasheet_fn(unit, stratagem_name="COMMAND RE-ROLL")
            ):
                return True
            return False

        if target_unit is not None:
            uid = self._heroic_intervention_target_id(target_unit)
            if not uid or uid in self._command_reroll_units_this_phase:
                return False
            return _can_repeat(target_unit)
        for cand in list(candidates or []):
            uid = self._heroic_intervention_target_id(cand)
            if not uid or uid in self._command_reroll_units_this_phase:
                continue
            if _can_repeat(cand):
                return True
        return False

    def _record_command_reroll_use(self, unit) -> None:
        uid = self._heroic_intervention_target_id(unit)
        if uid:
            self._command_reroll_units_this_phase.add(uid)

    def _grenade_repeat_allowed(self, *, target_unit=None, candidates=None) -> bool:
        if target_unit is not None:
            if not self._unit_can_use_primed_and_ready_grenade(
                target_unit,
                stratagem_name="GRENADE",
            ):
                return False
            uid = self._heroic_intervention_target_id(target_unit)
            return bool(uid and uid not in self._grenade_units_this_phase)
        for cand in list(candidates or []):
            if not self._unit_can_use_primed_and_ready_grenade(
                cand,
                stratagem_name="GRENADE",
            ):
                continue
            uid = self._heroic_intervention_target_id(cand)
            if uid and uid not in self._grenade_units_this_phase:
                return True
        return False

    def _record_grenade_use(self, unit) -> None:
        uid = self._heroic_intervention_target_id(unit)
        if uid:
            self._grenade_units_this_phase.add(uid)

    def _grenade_mortal_wound_threshold(self, target_unit) -> int:
        threshold = 4
        if target_unit is None:
            return threshold
        try:
            root = target_unit.get_attached_unit_root()
        except Exception:
            root = target_unit
        if root is None:
            return threshold
        try:
            members = list(root.get_attached_unit_members() or [])
        except Exception:
            members = [root]
        if not members:
            members = [root]
        for member in members:
            if member is None:
                continue
            sr = getattr(member, "special_rules", None)
            if not isinstance(sr, dict) or not bool(sr.get("enhancement_esoteric_explosives", False)):
                continue
            bearer = None
            bearer_id = str(sr.get("enhancement_bearer_model_id", "") or "")
            if bearer_id:
                for model in list(getattr(member, "models", []) or []):
                    model_id = str(get_entity_id(model) or getattr(model, "id", getattr(model, "_id", "")) or "")
                    if model_id == bearer_id:
                        bearer = model
                        break
            if bearer is None:
                get_bearer = getattr(member, "_get_enhancement_bearer_model", None)
                if callable(get_bearer):
                    try:
                        bearer = get_bearer()
                    except Exception:
                        bearer = None
            if bearer is None:
                continue
            try:
                alive_attr = getattr(bearer, "is_alive", True)
                bearer_alive = bool(alive_attr() if callable(alive_attr) else alive_attr)
            except Exception:
                bearer_alive = False
            if not bearer_alive:
                continue
            try:
                member_threshold = int(sr.get("enhancement_esoteric_explosives_grenade_mortal_threshold", 3) or 3)
            except Exception:
                member_threshold = 3
            threshold = min(int(threshold), int(max(2, member_threshold)))
        return int(max(2, threshold))

    def _evaluate_availability(
        self,
        stratagem: Stratagem,
        context: Dict[str, Any],
        *,
        is_active_turn: bool,
    ) -> Dict[str, Any]:
        result = {"available": False, "reason": None, "cp_cost": self._effective_cp_cost(stratagem, context)}
        name_u = (stratagem.name or "").strip().upper()
        phase_name = context.get("phase_name") or self._current_phase_name or ""

        if name_u and name_u in self._used_stratagems_this_phase:
            if name_u == "COMMAND RE-ROLL":
                if self._command_reroll_repeat_allowed(
                    target_unit=context.get("target_unit") or context.get("unit"),
                    candidates=context.get("candidates"),
                ):
                    pass
                else:
                    result["reason"] = "Already used this phase"
                    return result
            elif name_u == "HEROIC INTERVENTION":
                if self._heroic_intervention_repeat_allowed(
                    target_unit=context.get("target_unit") or context.get("unit"),
                    candidates=context.get("candidates"),
                    enemy_unit=context.get("enemy_unit"),
                ):
                    pass
                else:
                    result["reason"] = "Already used this phase"
                    return result
            elif name_u == "RAPID INGRESS":
                if self._rapid_ingress_repeat_allowed(
                    target_unit=context.get("target_unit") or context.get("unit"),
                    candidates=context.get("candidates"),
                ):
                    pass
                else:
                    result["reason"] = "Already used this phase"
                    return result
            elif name_u == "COUNTER-OFFENSIVE":
                if self._counter_offensive_daemonforge_available(
                    target_unit=context.get("target_unit") or context.get("unit"),
                    candidates=context.get("candidates"),
                ):
                    pass
                else:
                    result["reason"] = "Already used this phase"
                    return result
            elif name_u == "GRENADE":
                if self._grenade_repeat_allowed(
                    target_unit=context.get("target_unit") or context.get("unit"),
                    candidates=context.get("candidates"),
                ):
                    pass
                else:
                    result["reason"] = "Already used this phase"
                    return result
            else:
                result["reason"] = "Already used this phase"
                return result
        if name_u and self._used_once_per_battle.get(name_u, False):
            result["reason"] = "Once per battle used"
            return result
        if name_u == "OVERWATCH" or name_u == "FIRE OVERWATCH":
            if self._used_this_turn.get("OVERWATCH", False):
                if not self._overwatch_brutal_example_available(
                    target_unit=context.get("shooter_unit") or context.get("target_unit") or context.get("unit"),
                    candidates=context.get("candidates"),
                ):
                    result["reason"] = "Already used this turn"
                    return result
            enemy_unit = context.get("enemy_unit")
            no_overwatch = getattr(enemy_unit, "has_first_prince_slaanesh_no_overwatch", None)
            if callable(no_overwatch) and no_overwatch():
                result["reason"] = "Target cannot be overwatched"
                return result
            shooter_unit = context.get("shooter_unit") or context.get("target_unit") or context.get("unit")
            if self._is_overwatch_shooter_blocked_this_turn(shooter_unit):
                result["reason"] = "Unit cannot use Fire Overwatch this turn"
                return result
            blocked_fn = getattr(enemy_unit, "is_overwatch_prevented_against", None)
            if callable(blocked_fn):
                try:
                    if blocked_fn(shooter_unit, game=self.game):
                        result["reason"] = "Target cannot be overwatched"
                        return result
                except Exception:
                    raise
        phase_ok = stratagem.is_phase_allowed(phase_name)
        if name_u == "FLICKERING REALITY":
            if phase_name and str(phase_name).strip().lower() == "fight phase":
                phase_ok = True
        if not phase_ok:
            result["reason"] = "Wrong phase"
            return result
        if not stratagem.is_turn_allowed(is_active_turn):
            result["reason"] = "Wrong turn"
            return result

        if int(getattr(self.player, "command_points", 0) or 0) < int(result["cp_cost"] or 0):
            if name_u in ("OVERWATCH", "FIRE OVERWATCH") and self._overwatch_zero_cp_available(
                target_unit=context.get("shooter_unit") or context.get("target_unit") or context.get("unit"),
                candidates=context.get("candidates"),
            ):
                result["cp_cost"] = 0
            else:
                result["reason"] = "Not enough CP"
                return result

        # Targeting restrictions for provided context
        target = _extract_friendly_target_unit_from_kwargs(context)
        if target is not None and name_u not in ("BLOOD OFFERING", "A GRIM WARNING", "PALL OF DREAD"):
            if _unit_cannot_be_target_of_stratagem(target):
                if name_u != "INSANE BRAVERY":
                    result["reason"] = "Target cannot be selected"
                    return result

        # Adeptus Custodes (Lions of the Emperor): UNLEASH THE LIONS
        if name_u == "UNLEASH THE LIONS":
            if self._unleash_lions_detachment_manager() is None:
                result["reason"] = "Wrong detachment"
                return result
            if target is not None:
                if not self._unleash_lions_is_valid_target(target):
                    result["reason"] = "Requires Allarus or Aquilon unit on battlefield"
                    return result
            else:
                if not self._unleash_lions_candidates():
                    result["reason"] = "Requires valid target"
                    return result

        # Adeptus Custodes (Lions of the Emperor): MANOEUVRE AND FIRE
        if name_u == "MANOEUVRE AND FIRE":
            if self._gilded_champion_detachment_manager() is None:
                result["reason"] = "Wrong detachment"
                return result
            if target is not None and not self._is_adeptus_custodes_unit(target):
                result["reason"] = "Requires ADEPTUS CUSTODES unit"
                return result

        # Last pass: delegate to stratagem conditions
        if name_u in ("BLOOD OFFERING", "A GRIM WARNING"):
            if context.get("objective_candidates"):
                result["available"] = True
                result["reason"] = None
                return result
        if name_u == "BLITZING FIREPOWER":
            if self._blitzing_firepower_candidates():
                result["available"] = True
                result["reason"] = None
                return result
        if name_u == "SOULSIGHT":
            soulsight_candidates = list(context.get("candidates") or [])
            if not soulsight_candidates:
                soulsight_candidates = list(self._aeldari_soulsight_candidates_for_active_detachment() or [])
            if soulsight_candidates:
                result["available"] = True
                result["reason"] = None
                return result
            result["reason"] = "Requires your Shooting phase and an eligible SOULSIGHT target that has not shot"
            return result
        if name_u == "PRESENTIMENT OF DREAD":
            phase_name_l = str(context.get("phase_name") or self._current_phase_name or "").strip().lower()
            if phase_name_l and phase_name_l != "command phase":
                result["reason"] = "Requires Command phase"
                return result
            source_candidates = list(context.get("candidates") or [])
            if not source_candidates:
                source_candidates = list(self._aeldari_seer_presentiment_psyker_candidates() or [])
            if source_candidates:
                result["available"] = True
                result["reason"] = None
                return result
            result["reason"] = (
                "Requires Command phase and an ASURYANI PSYKER with a visible enemy unit within 18\" to force a Battle-shock test at -1"
            )
            return result
        if name_u == "FOREWARNED":
            phase_name_l = str(context.get("phase_name") or self._current_phase_name or "").strip().lower()
            if phase_name_l and phase_name_l != "fight phase":
                result["reason"] = "Requires Fight phase trigger"
                return result
            target_units = list(context.get("target_units") or [])
            candidates = list(context.get("candidates") or [])
            if not candidates:
                candidates = list(self._aeldari_seer_forewarned_candidates(target_units=target_units) or [])
            if candidates:
                result["available"] = True
                result["reason"] = None
                return result
            result["reason"] = (
                "Requires Fight phase trigger after enemy targets are selected, targeting an eligible ASURYANI INFANTRY non-WRAITH CONSTRUCT unit within 9\" of one of your ASURYANI PSYKER units"
            )
            return result
        if name_u == "FANGS OF THE BROOD":
            phase_name_l = str(context.get("phase_name") or self._current_phase_name or "").strip().lower()
            if phase_name_l and phase_name_l != "fight phase":
                result["reason"] = "Requires Fight phase"
                return result
            candidates = list(context.get("candidates") or [])
            if not candidates:
                candidates = list(self._aeldari_serpents_fangs_candidates() or [])
            if candidates:
                result["available"] = True
