    def _on_unit_shooting_resolved_fire_and_fade(self, attacker_unit=None, **kwargs):
        """
        Reaction window for FIRE AND FADE:
        Your Shooting phase, just after an ASURYANI INFANTRY unit has shot.
        """
        try:
            if attacker_unit is None or self.game is None:
                return
            if (self._current_phase_name or "").strip().lower() != "shooting phase":
                return
            if not self._is_warhost_detachment():
                return
            # Only offer to the active player (your turn)
            active_player = getattr(self.game, "get_current_player", lambda: None)()
            if active_player is not self.player:
                return
            try:
                if attacker_unit.get_parent_army().player is not self.player:
                    return
            except Exception:
                raise
            s = self.get_by_name("FIRE AND FADE")
            if not s:
                return
            if self.player.command_points < s.cp_cost:
                return
            if (s.name or "").strip().upper() in self._used_stratagems_this_phase:
                return
            try:
                root = attacker_unit.get_attached_unit_root()
            except Exception:
                raise
            if root is None:
                return
            if _unit_cannot_be_target_of_stratagem(root):
                return
            try:
                if not root.has_any_keyword("ASURYANI"):
                    return
                if not root.has_keyword("INFANTRY"):
                    return
                if root.has_keyword("WRAITH CONSTRUCT"):
                    return
                if root.has_keyword("AIRCRAFT") or bool(getattr(root, "is_aircraft", False)):
                    return
                if str(getattr(root, "name", "") or "").strip().upper() == "ASURMEN":
                    return
            except Exception:
                raise
            if not s.can_use(self.player, self.game, phase_name="Shooting phase", unit=root):
                return
            for r in self._pending_reactions:
                try:
                    if r.get("event") == "unit_shooting_resolved" and r.get("stratagem") == s.name and r.get("unit") is root:
                        return
                except Exception:
                    raise
            self._queue_reaction({
                "event": "unit_shooting_resolved",
                "phase_name": "Shooting phase",
                "stratagem": s.name,
                "cp_cost": s.cp_cost,
                "unit": root,
                "target_unit": root,
            })
        except Exception:
            raise

    def _on_unit_shooting_resolved_fury_unleashed(self, attacker_unit=None, hits_by_target=None, **_kwargs):
        """
        Reaction window for FURY UNLEASHED:
        Opponent's Shooting phase, just after an enemy unit has shot and hit a WORLD EATERS RHINO.
        """
        try:
            if attacker_unit is None or self.game is None:
                return
            if (self._current_phase_name or "").strip().lower() != "shooting phase":
                return
            active_player = getattr(self.game, "get_current_player", lambda: None)()
            if active_player is self.player:
                return
            if not self._is_goretrack_onslaught():
                return
            s = self.get_by_name("FURY UNLEASHED")
            if not s:
                return
            if self.player.command_points < s.cp_cost:
                return
            if (s.name or "").strip().upper() in self._used_stratagems_this_phase:
                return
            targets = []
            atk_key = self._attacker_unit_key(attacker_unit)
            if isinstance(hits_by_target, dict):
                for t, hits in hits_by_target.items():
                    try:
                        if int(hits or 0) <= 0:
                            continue
                    except Exception:
                        continue
                    targets.append(t)
            if not targets and atk_key:
                targets = list(self._recent_shooting_targets.get(atk_key) or [])
            if atk_key:
                self._recent_shooting_targets.pop(atk_key, None)
            mgr = self._get_world_eaters_mgr()
            candidates = []
            seen = set()
            for t in list(targets or []):
                try:
                    root = t.get_attached_unit_root()
                except Exception:
                    raise
                if root is None:
                    continue
                try:
                    uid = get_entity_id(root)
                except Exception:
                    raise
                if uid in seen:
                    continue
                seen.add(uid)
                try:
                    if not root.is_alive():
                        continue
                except Exception:
                    raise
                try:
                    if root.get_parent_army().player is not self.player:
                        continue
                except Exception:
                    raise
                try:
                    if not getattr(root, "deployed", False):
                        continue
                except Exception:
                    raise
                try:
                    if getattr(root, "is_in_reserves", lambda: False)():
                        continue
                except Exception:
                    raise
                try:
                    if _unit_cannot_be_target_of_stratagem(root):
                        continue
                except Exception:
                    raise
                if not self._is_world_eaters_unit(root, mgr=mgr):
                    continue
                try:
                    if not root.has_keyword("RHINO"):
                        continue
                except Exception:
                    continue
                passengers = self._goretrack_embarked_units(
                    root,
                    require_world_eaters=True,
                    require_khorne_berzerkers=True,
                )
                if not passengers:
                    continue
                try:
                    sr = getattr(root, "special_rules", None)
                except Exception:
                    sr = None
                if isinstance(sr, dict):
                    phase_key = self._goretrack_phase_key()
                    if str(sr.get("goretrack_unrelenting_advance_phase_key", "") or "") == phase_key:
                        continue
                candidates.append(root)
            if not candidates:
                return
            for r in self._pending_reactions:
                try:
                    if r.get("event") == "unit_shooting_resolved" and r.get("stratagem") == s.name and r.get("enemy_unit") is attacker_unit:
                        return
                except Exception:
                    raise
            payload = {
                "event": "unit_shooting_resolved",
                "phase_name": "Shooting phase",
                "stratagem": s.name,
                "cp_cost": s.cp_cost,
                "enemy_unit": attacker_unit,
                "candidates": candidates,
            }
            if len(candidates) == 1:
                payload["target_unit"] = candidates[0]
            self._queue_reaction(payload)
        except Exception:
            raise

